use super::*;

// Generated by the independent Python reference, not the Rust encoder.
const MAIN: &str = "gnb1zq9g4z52329g4z52329g4z52329g4z5232lk8szw";
const TEST: &str = "tgnb1zq9g4z52329g4z52329g4z52329g4z5232ed3tuc";
const POLICY_MAIN: &str = "gnb1zp9skzctpv9skzctpv9skzctpv9skzctpv9skzctpv9skzctpv9skqamypv7";
const POLICY_TEST: &str = "tgnb1zp9skzctpv9skzctpv9skzctpv9skzctpv9skzctpv9skzctpv9skqzctyfu";

#[test]
fn address_frontends_cli_v2_payment_destination_keeps_wallet_network() {
    use gnb::address::{Address, Network};
    for (network, valid, wrong) in [(Network::Mainnet, MAIN, TEST), (Network::Testnet, TEST, MAIN)] {
        let wallet = Address::from_hash([42; 20], network).to_string();
        assert_eq!(checked_destination(&wallet, &wallet), Ok("2a".repeat(20)));
        assert_eq!(checked_destination(valid, &wallet), Ok("2a".repeat(20)));
        assert_eq!(checked_destination(wrong, &wallet), Err("destination address network differs from wallet"));
    }
}

#[test]
fn address_frontends_cli_v2_policy_and_vault_destinations_keep_spend_network() {
    use gnb::address::{Network, PolicyAddress};
    let script = [vec![gnb::core::policy::POLICY_TAG], vec![44; 32]].concat();
    for (network, valid, wrong) in [(Network::Mainnet, POLICY_MAIN, POLICY_TEST), (Network::Testnet, POLICY_TEST, POLICY_MAIN)] {
        let legacy = PolicyAddress::from_script(&script, network).unwrap().to_string();
        assert_eq!(destination_on(&legacy, network, "recipient").unwrap(), script);
        assert_eq!(destination_on(valid, network, "recipient").unwrap(), script);
        assert!(destination_on(wrong, network, "recipient").unwrap_err().contains("this spend is on"));
    }
}
